// Small game physics, not a measured sports-training or learning assessment.
export const PASS_DT=1/120,PASS_RADIUS=.22,PASS_GRAVITY=9.8,PASS_FLOOR=.06;
export const PASS_START={x:-2.65,z:3.3};
export const PASS_BOUNDS={minX:-3.2,maxX:-1.4,minZ:2.75,maxZ:4.95};
export const PASS_PATTERNS=[
 {name:'처음 주고받기',turtle:{x:2.55,z:3.3},receive:{x:-2.15,z:4.65},posts:[]},
 {name:'옆으로 열린 길',turtle:{x:2.55,z:4.65},receive:{x:-2.5,z:3.05},posts:[{x:0,z:3.3}]},
 {name:'한 걸음 옮겨서',turtle:{x:2.95,z:2.95},receive:{x:-2.2,z:4.9},posts:[{x:0,z:3.2}]},
 {name:'좁은 틈 사이로',turtle:{x:1.85,z:4.65},receive:{x:-2.45,z:3.1},posts:[{x:-.05,z:3.05},{x:0,z:4.7}]},
 {name:'움직이는 가림막',turtle:{x:3.15,z:4.35},receive:{x:-1.7,z:4.95},posts:[{x:.1,z:3.8,moving:true},{x:1.35,z:2.85}]}
];
const clone=x=>JSON.parse(JSON.stringify(x)),clamp=(x,a,b)=>Math.max(a,Math.min(b,x)),finite=(x,f)=>Number.isFinite(x)?x:f;
export const DEFAULT_PASS_ANCHORS={player:{x:.6837305237287042,y:1.1377228881720816,z:-.545},turtle:{x:-.58,y:.473,z:0}};
export const passPosts=(index,time)=>PASS_PATTERNS[index].posts.map(p=>({...p,z:p.z+(p.moving?Math.sin(time*1.35)*.55:0),radius:.22,height:1.65}));
export function passHand(player,anchor){return{x:player.x+anchor.x,y:anchor.y,z:player.z+anchor.z};}
const add=(a,b)=>({x:a.x+b.x,y:a.y+b.y,z:a.z+b.z}),lerp=(a,b,t)=>({x:a.x+(b.x-a.x)*t,y:a.y+(b.y-a.y)*t,z:a.z+(b.z-a.z)*t});
function sphereHit(a,b,center,r){const dx=b.x-a.x,dy=b.y-a.y,dz=b.z-a.z,x=a.x-center.x,y=a.y-center.y,z=a.z-center.z,A=dx*dx+dy*dy+dz*dz,C=x*x+y*y+z*z-r*r;if(C<=0)return 0;if(A<1e-14)return null;const B=2*(x*dx+y*dy+z*dz),D=B*B-4*A*C;if(D<0)return null;const t=(-B-Math.sqrt(D))/(2*A);return t>=0&&t<=1?t:null;}
function postHit(a,b,old,p){const x=a.x-old.x,z=a.z-old.z,dx=b.x-a.x-(p.x-old.x),dz=b.z-a.z-(p.z-old.z),r=PASS_RADIUS+p.radius,A=dx*dx+dz*dz,B=2*(x*dx+z*dz),C=x*x+z*z-r*r;let t=C<=0?0:null;if(t===null&&A>1e-14){const D=B*B-4*A*C;if(D>=0){const n=(-B-Math.sqrt(D))/(2*A);if(n>=0&&n<=1)t=n;}}if(t===null)return null;const y=a.y+(b.y-a.y)*t;return y+PASS_RADIUS>=PASS_FLOOR&&y-PASS_RADIUS<=p.height?t:null;}
function launchVelocity(settings){const yaw=settings.yawDeg*Math.PI/180,pitch=20*Math.PI/180,speed=4.5+settings.power*.045;return{x:speed*Math.cos(pitch)*Math.cos(yaw),y:speed*Math.sin(pitch),z:speed*Math.cos(pitch)*Math.sin(yaw)};}
export function suggestedPass(origin,target){const dx=target.x-origin.x,dz=target.z-origin.z,d=Math.hypot(dx,dz),p=20*Math.PI/180,speed=Math.sqrt(PASS_GRAVITY*d*d/(2*Math.cos(p)**2*(d*Math.tan(p)+origin.y-target.y)));return{yawDeg:Math.atan2(dz,dx)*180/Math.PI,power:clamp((speed-4.5)/.045,0,100)};}
function finish(s,success,reason){s.phase='result';s.success=success;s.reason=reason;s.complete=s.mode==='challenge'&&s.attempts>=5;if(success)s.score++;}
function flightStep(s,anchors,dt,previousHand){const a={...s.position},b=add(a,{x:s.velocity.x*dt,y:s.velocity.y*dt-.5*PASS_GRAVITY*dt*dt,z:s.velocity.z*dt}),events=[];s.velocity.y-=PASS_GRAVITY*dt;s.elapsed+=dt;const posts=passPosts(s.pattern,s.clock),oldPosts=passPosts(s.pattern,s.clock-dt);let contact=null;
 for(let i=0;i<posts.length;i++){const t=postHit(a,b,oldPosts[i],posts[i]);if(t!==null&&(!contact||t<contact.t))contact={t,type:'obstacle',post:posts[i]};}
 if(b.y<=PASS_FLOOR+PASS_RADIUS){const t=clamp((a.y-(PASS_FLOOR+PASS_RADIUS))/(a.y-b.y),0,1);if(!contact||t<contact.t)contact={t,type:'floor'};}
 if(s.phase==='outbound'||s.phase==='return-flight'){const target=s.phase==='outbound'?s.turtleHand:passHand(s.player,anchors.player),old=s.phase==='outbound'?target:previousHand;const relA={x:a.x-old.x,y:a.y-old.y,z:a.z-old.z},relB={x:b.x-target.x,y:b.y-target.y,z:b.z-target.z};const t=sphereHit(relA,relB,{x:0,y:0,z:0},.34);if(t!==null&&(!contact||t<contact.t))contact={t,type:s.phase==='outbound'?'turtle-catch':'player-catch',target};}
 if(contact){s.position=lerp(a,b,contact.t);events.push({type:contact.type,position:{...s.position}});if(contact.type==='turtle-catch'){s.phase='turtle-held';s.owner='turtle';s.hold=0;s.catchFrom={...s.position};s.velocity={x:0,y:0,z:0};}else if(contact.type==='player-catch'){s.phase='catching';s.owner='player';s.hold=0;s.catchFrom={...s.position};s.velocity={x:0,y:0,z:0};}else if(contact.type==='obstacle'){const dx=s.position.x-contact.post.x,dz=s.position.z-contact.post.z,len=Math.hypot(dx,dz)||1,nx=dx/len,nz=dz/len,dot=s.velocity.x*nx+s.velocity.z*nz;s.velocity.x=(s.velocity.x-2*dot*nx)*.42;s.velocity.z=(s.velocity.z-2*dot*nz)*.42;s.position.x=contact.post.x+nx*(contact.post.radius+PASS_RADIUS+.002);s.position.z=contact.post.z+nz*(contact.post.radius+PASS_RADIUS+.002);s.phase='miss-flight';s.reason='가림막에 닿았어요. 옆으로 움직이거나 열린 때를 기다려요';}else{s.position.y=PASS_FLOOR+PASS_RADIUS;s.velocity.y=Math.abs(s.velocity.y)*.38;s.velocity.x*=.55;s.velocity.z*=.55;s.bounces++;if(s.phase!=='miss-flight'){s.reason=s.phase==='return-flight'?'공이 지나갔어요. 금빛 원으로 움직여 손으로 받아요':'조금 짧거나 빗나갔어요. 점선과 힘을 다시 살펴봐요';s.phase='miss-flight';}if(s.bounces>=3||Math.abs(s.velocity.y)<.28){s.owner='ground';s.velocity={x:0,y:0,z:0};finish(s,false,s.reason);}}}else s.position=b;
 if(s.elapsed>6||Math.abs(s.position.x)>10||s.position.z<-1||s.position.z>8){s.position.y=PASS_FLOOR+PASS_RADIUS;s.owner='ground';finish(s,false,s.reason||'공이 멀리 갔어요. 힘과 방향을 조금 줄여 봐요');}
 return events;
}
export function createPassingModel({mode='practice',pattern=0,anchors=DEFAULT_PASS_ANCHORS,partnerName='거북이'}={}){
 anchors=clone(anchors);for(const a of Object.values(anchors))if(!['x','y','z'].every(k=>Number.isFinite(a[k])))throw Error('Invalid pass anchors');let s,accumulator=0,moveInput={x:0,z:0};
 function init(which=0){const prior=s,patternIndex=clamp(Math.trunc(finite(which,0)),0,4),turtle=PASS_PATTERNS[patternIndex].turtle,player={...PASS_START},turtleHand=passHand(turtle,anchors.turtle);s={mode:mode==='challenge'?'challenge':'practice',pattern:patternIndex,phase:'aiming',owner:'player',player,turtle:{...turtle},turtleHand,position:passHand(player,anchors.player),velocity:{x:0,y:0,z:0},settings:prior?.settings??suggestedPass(passHand(player,anchors.player),turtleHand),clock:0,elapsed:0,tick:0,attempts:prior?.attempts??0,score:prior?.score??0,paused:false,complete:false,receiveSpot:null,hold:0,bounces:0,reason:'점선을 보고 방향과 힘을 골라요',success:false};moveInput={x:0,z:0};accumulator=0;}
 function move(x,z){moveInput={x:clamp(finite(x,0),-1,1),z:clamp(finite(z,0),-1,1)};}
 function aim(settings){if(s.phase!=='aiming'||s.paused)return false;s.settings={yawDeg:clamp(finite(settings.yawDeg,s.settings.yawDeg),-35,35),power:clamp(finite(settings.power,s.settings.power),0,100)};return true;}
 function launch(){if(s.phase!=='aiming'||s.paused||s.complete)return false;s.position=passHand(s.player,anchors.player);s.velocity=launchVelocity(s.settings);s.phase='outbound';s.owner='flight';s.elapsed=0;s.attempts++;s.bounces=0;let receive={...PASS_PATTERNS[s.pattern].receive};if(Math.hypot(receive.x-s.player.x,receive.z-s.player.z)<1){receive=[{x:-2.9,z:2.85},{x:-1.7,z:4.85}].sort((a,b)=>Math.hypot(b.x-s.player.x,b.z-s.player.z)-Math.hypot(a.x-s.player.x,a.z-s.player.z))[0];}s.receiveSpot=receive;s.reason=partnerName+'에게 패스! 금빛 원으로 움직여 돌아오는 공을 준비해요';return true;}
 function advance(dt){if(s.paused||!Number.isFinite(dt)||dt<=0)return[];accumulator+=Math.min(dt,.1);const events=[];while(accumulator+1e-12>=PASS_DT){accumulator-=PASS_DT;s.clock+=PASS_DT;s.tick++;const previousHand=passHand(s.player,anchors.player),n=Math.max(1,Math.hypot(moveInput.x,moveInput.z));s.player.x=clamp(s.player.x+moveInput.x/n*2.1*PASS_DT,PASS_BOUNDS.minX,PASS_BOUNDS.maxX);s.player.z=clamp(s.player.z+moveInput.z/n*2.1*PASS_DT,PASS_BOUNDS.minZ,PASS_BOUNDS.maxZ);
   if(s.phase==='aiming'||s.phase==='result'&&s.owner==='player')s.position=passHand(s.player,anchors.player);
   else if(s.phase==='turtle-held'){s.hold+=PASS_DT;s.position=lerp(s.catchFrom,s.turtleHand,Math.min(s.hold/.14,1));if(s.hold>=.7){const to=passHand(s.receiveSpot,anchors.player),time=1.25;s.position={...s.turtleHand};s.velocity={x:(to.x-s.position.x)/time,y:(to.y-s.position.y+.5*PASS_GRAVITY*time*time)/time,z:(to.z-s.position.z)/time};s.phase='return-flight';s.owner='flight';s.elapsed=0;events.push({type:'return',target:{...s.receiveSpot}});}}
   else if(s.phase==='catching'){s.hold+=PASS_DT;s.position=lerp(s.catchFrom,passHand(s.player,anchors.player),Math.min(s.hold/.14,1));if(s.hold>=.14){finish(s,true,'받았어요! 보내고, 빈자리로 움직이고, 다시 받았어요');events.push({type:'success'});}}
   else if(s.phase!=='result')events.push(...flightStep(s,anchors,PASS_DT,previousHand));
  }return events;}
 function predict(){const copy=clone(s);copy.phase='outbound';copy.position=passHand(copy.player,anchors.player);copy.velocity=launchVelocity(copy.settings);copy.elapsed=0;copy.bounces=0;const points=[{...copy.position}];let event=null;for(let i=0;i<720;i++){copy.clock+=PASS_DT;const events=flightStep(copy,anchors,PASS_DT,passHand(copy.player,anchors.player));if(i%4===0)points.push({...copy.position});if(events.length){event=events[0];points.push({...copy.position});break;}}return{points,event,position:{...copy.position}};}
 function next(){if(s.phase!=='result'||s.complete)return false;init((s.pattern+1)%5);return true;}
 function reset(nextMode=mode){mode=nextMode==='challenge'?'challenge':'practice';s=null;init(0);}
 init(pattern);return{aim,move,launch,advance,predict,next,reset,pause(){s.paused=true;move(0,0);},resume(){s.paused=false;},snapshot:()=>clone({...s,posts:passPosts(s.pattern,s.clock)}),dispose(){move(0,0);s.paused=true;}};
}
